$checks=['PHP 8.2 ou superior'=>version_compare(PHP_VERSION,'8.2.0','>='),'PDO MySQL'=>extension_loaded('pdo_mysql'),'OpenSSL'=>extension_loaded('openssl'),'ZIP'=>extension_loaded('zip'),'Multibyte'=>extension_loaded('mbstring'),'Fileinfo'=>extension_loaded('fileinfo'),'Pasta privada gravável'=>is_writable(TR_PRIVATE),'Sessões privadas'=>is_writable(TR_PRIVATE.'/runtime/sessions'),'Base DEMONSTRAÇÃO'=>is_file(TR_RELEASE.'/data/base.json'),'Chave de instalação'=>is_file(TR_PRIVATE.'/install.key')];$error='';$done=false;
