 $lock=fopen(TR_PRIVATE.'/runtime/install.lock','c');if(!flock($lock,LOCK_EX|LOCK_NB))throw new Fault('Outra instalação está em andamento.');if(is_file(TR_PRIVATE.'/installed.lock'))throw new Fault('O sistema já foi instalado.');
 $originPolicy=validateInstallationOrigin(need($_POST['url']??'','endereço do sistema',240),$_SERVER,TR_PRIVATE.'/runtime/http-bootstrap.json');$url=$originPolicy['url'];
 $host=need($_POST['db_host']??'','servidor MySQL',190);$name=need($_POST['db_name']??'','banco',100);$dbUser=need($_POST['db_user']??'','usuário MySQL',100);if(!preg_match('/^[a-zA-Z0-9_.-]+$/',$host)||!preg_match('/^[a-zA-Z0-9_]+$/',$name))throw new Fault('Servidor ou nome do banco inválido.');$port=(int)num($_POST['db_port']??3306,1,65535,'porta');$email=strtolower(need($_POST['admin_email']??'','e-mail do administrador',190));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new Fault('E-mail inválido.');$adminName=need($_POST['admin_name']??'','nome do administrador',120);$password=(string)($_POST['admin_password']??'');passwordRules($password);if($password!==($_POST['admin_confirm']??''))throw new Fault('As senhas do administrador não coincidem.');
